/// Applies "deposit N" / "withdraw N" operations to a balance starting at 0.
pub fn run_ops(ops: List[Str]) -> Result[Int, Str] {
  var bal = 0
  for i in range(0, ops.len()) {
    let pos = i + 1
    let parts = ops.get_or(i, "").split(" ")
    if parts.len() != 2 {
      return Err("bad op at op {pos}")
    }
    let kind = parts.get_or(0, "")
    let amount = match parts.get_or(1, "").to_int() {
      Some(n) => n,
      None => -1,
    }
    if amount < 0 {
      return Err("bad op at op {pos}")
    }
    if kind == "deposit" {
      bal = bal + amount
    } else if kind == "withdraw" {
      if amount > bal {
        return Err("insufficient funds at op {pos}")
      }
      bal = bal - amount
    } else {
      return Err("bad op at op {pos}")
    }
  }
  return Ok(bal)
}
